import { defineConfig } from 'vite-plus';

export default defineConfig({
  fmt: {
    singleQuote: true,
    semi: true,
    trailingComma: 'es5',
    printWidth: 80,
    sortPackageJson: false,
    // `docs/sample-messages.md` is generated by src/test/sample-messages.test.ts
    // and compared byte for byte; reformatting it would fail that test.
    // `examples/*` are outside the root toolchain altogether (CLAUDE.md).
    ignorePatterns: [
      'dist',
      'node_modules',
      'pnpm-lock.yaml',
      'docs/sample-messages.md',
      'examples/**',
    ],
  },

  lint: {
    plugins: ['typescript'],
    categories: { correctness: 'error' },
    rules: {
      'no-unused-vars': ['error', { argsIgnorePattern: '^_' }],
      'no-console': ['error', { allow: ['warn', 'error'] }],
      'typescript/no-explicit-any': 'error',
    },
    overrides: [
      {
        files: ['**/*.test.ts'],
        rules: {
          'typescript/no-explicit-any': 'off',
          // A vi.fn() on a plain object literal is not a class method, so passing
          // it to expect() cannot lose `this`. The rule cannot tell the difference.
          'typescript/unbound-method': 'off',
          // The tests stringify what a stub returned (a Buffer, a fetch input).
          // A value of the wrong type fails the assertion that compares it, so
          // `[object Object]` cannot slip through silently here.
          'typescript/no-base-to-string': 'off',
        },
      },
    ],
    // `examples/*` are outside the root toolchain altogether (CLAUDE.md).
    ignorePatterns: ['dist', 'node_modules', 'examples/**'],
    options: { typeAware: true, typeCheck: true },
  },

  test: {
    environment: 'node',
    include: ['src/**/*.test.ts'],
    // Registers the `toHavePosted` / `toHaveDispatched` / ... matchers the
    // `@chat-adapter/tests` contract suites assert with; without it those
    // suites fail on an unknown matcher rather than on adapter behaviour.
    // It registers them on the `expect` of the `vitest` that
    // `@chat-adapter/tests` resolves, so that has to be the copy `vp test`
    // runs. That is the one `vite-plus` bundles, which is why `vitest` is not a
    // direct dependency: a second one would leave the matchers on an `expect`
    // the suites never call. `pnpm why vitest` must show a single version.
    setupFiles: ['@chat-adapter/tests/setup'],
  },

  pack: {
    entry: { index: 'src/index.ts' },
    format: ['esm'],
    target: 'es2022',
    dts: true,
    // tsdown turns this on by default whenever `platform` resolves to `node`,
    // which would publish `index.mjs`. Every `@chat-adapter/*` adapter ships a
    // plain `index.js`, and with `"type": "module"` the bare extension is
    // already unambiguous, so the fixed one only makes our paths differ.
    fixedExtension: false,
    publint: true,
    attw: {
      // `strict` also requires the package to resolve from a `require()` call,
      // which no ESM-only package can satisfy on the Node versions that predate
      // `require(esm)`. `esm-only` is attw's own profile for that shape.
      profile: 'esm-only',
      // The default is `warn`, which reports problems without failing the build.
      level: 'error',
    },
  },

  staged: {
    '*': 'vp check --fix',
  },
});
